// --- PRODUCTION CODE: ALL GROUPS ENABLED ---

const body = $json.body || {};
const eventType = body.event;
let data = body.data;

// 1. DATA NORMALIZATION
if (Array.isArray(data)) {
    data = data[0];
}

// 2. SAFETY CHECKS
if (!data) return [];

// CRITICAL SAFETY SHIELD: Ignore messages sent by the bot itself
if (data.key && data.key.fromMe) return []; 

// CRITICAL SAFETY SHIELD: Ignore emoji reactions or message updates (prevents empty text errors)
if (data.message?.reactionMessage || eventType === 'messages.update') return [];
// ---------------------------------

// CRITICAL SAFETY SHIELD: Ignore messages sent by the bot itself
if (data.key && data.key.fromMe) return []; 
// ---------------------------------------

// 3. RECURSIVE SEARCH FUNCTION
function findBase64Recursive(obj) {
    if (!obj || typeof obj !== 'object') return null;
    if (obj.base64) return obj.base64;

    for (const key in obj) {
        if (Object.prototype.hasOwnProperty.call(obj, key)) {
             if (typeof obj[key] === 'object') {
                 const found = findBase64Recursive(obj[key]);
                 if (found) return found;
             }
        }
    }
    return null;
}

// 4. EXECUTE SEARCH
let rawBase64 = findBase64Recursive(data);

// Fallback: Look for thumbnail if full file missing
if (!rawBase64) {
    const findThumb = (obj) => {
        if (!obj || typeof obj !== 'object') return null;
        if (obj.jpegThumbnail) return obj.jpegThumbnail;
        for (const k in obj) {
            if (typeof obj[k] === 'object') {
                const f = findThumb(obj[k]);
                if (f) return f;
            }
        }
        return null;
    };
    rawBase64 = findThumb(data);
}

// 5. SANITIZE DATA
if (rawBase64 && typeof rawBase64 === 'object' && rawBase64.data) {
    rawBase64 = Buffer.from(rawBase64.data).toString('base64');
}

// 6. EXTRACT MESSAGE DETAILS
const messageContent = data.message || {};
const senderName = data.pushName || (data.key ? data.key.participant : "WhatsApp User") || "Unknown";
const waGroupId = data.key ? data.key.remoteJid : "";

// --- 7. CONFIGURATION: FULL CHANNEL MAP ---
const CHANNEL_MAP = {
  // Test group
  "120363000000000008@g.us": "C0EXAMPL001", 

  // Team group 1
  "120363000000000003@g.us": "C0EXAMPL003",

  // Team group 2
  "120363000000000014@g.us": "C0EXAMPL004",

  // Team group 3
  "120363000000000001@g.us": "C0EXAMPL002",

  // Team group 4
  "120363000000000010@g.us": "C0EXAMPL005",

  // Team group 5
  "120363000000000004@g.us": "C0EXAMPL006",

  // Team group 6
  "120363000000000006@g.us": "C0EXAMPL007",

  // Team group 7
  "120363000000000012@g.us": "C0EXAMPL008",

  // Team group 8
  "120363000000000007@g.us": "C0EXAMPL010",

  // Team group 9
  "120363000000000011@g.us": "C0EXAMPL011",

  // Team group 10
  "120363000000000017@g.us": "C0EXAMPL009",

  // Team group 11
  "120363000000000005@g.us": "C0EXAMPL013",

  // Team group 12
  "120363000000000009@g.us": "C0EXAMPL015",

  // Team group 13
  "120363000000000015@g.us": "C0EXAMPL014",

  // Team group 14
  "120363000000000002@g.us": "C0EXAMPL012",

  // Team group 15
  "120363000000000016@g.us": "C0EXAMPL016",

  // Engineering test group (EOD summary logging only)
  "120363000000000013@g.us": "SUMMARY_ONLY"
};

const targetChannelId = CHANNEL_MAP[waGroupId];

// FILTER: If message is from a group NOT in this list, stop.
if (!targetChannelId) return [];

// 8. DETERMINE MEDIA TYPE & TEXT EXTRACTION
let messageText = "";
let fileName = "file.bin";
let mimeType = "application/octet-stream";
let isMedia = false;

if (messageContent.videoMessage) {
    isMedia = true;
    fileName = "video.mp4";
    mimeType = "video/mp4";
    messageText = messageContent.videoMessage.caption || "🎥 Video";
} else if (messageContent.imageMessage) {
    isMedia = true;
    fileName = "image.jpg";
    mimeType = "image/jpeg";
    messageText = messageContent.imageMessage.caption || "📷 Image";
} else if (messageContent.audioMessage) {
    isMedia = true;
    fileName = "audio.ogg";
    mimeType = "audio/ogg";
    messageText = "🎤 Voice Note";
} else if (messageContent.documentMessage) {
    isMedia = true;
    fileName = messageContent.documentMessage.fileName || "doc.pdf";
    mimeType = messageContent.documentMessage.mimetype || "application/pdf";
    messageText = messageContent.documentMessage.caption || "📄 Document";
} else {
    // TEXT & LINK HANDLING: Checks for standard conversation OR extended links/previews
    messageText = messageContent.conversation || messageContent.extendedTextMessage?.text || "";
}

// 9. FINAL VALIDATION & EMPTY MESSAGE SHIELD
if (isMedia && !rawBase64) {
    messageText += "\n(⚠️ Error: Media not downloaded)";
    isMedia = false; 
}

// CRITICAL SHIELD: If there is no media AND the extracted text is empty, stop the workflow.
// This prevents empty "WhatsApp Bridge" messages from looping into Slack.
if (!messageText && !isMedia) {
    return []; 
}

// 10. OUTPUT GENERATION
return {
  json: {
    slackChannel: targetChannelId,
    messageText: messageText,
    senderName: senderName,
    isMedia: isMedia,
    waGroupId: waGroupId
  },
  binary: (isMedia && rawBase64) ? {
    data: {
      data: rawBase64,
      mimeType: mimeType,
      fileExtension: fileName.split('.').pop(),
      fileName: fileName
    }
  } : undefined
};

// PRODUCTION DUPLICATE CHECK - NO EXTERNAL MODULES REQUIRED
const msgId = $json.body?.data?.key?.id;
if (!msgId) return { json: { isDuplicate: false } };

// Use n8n's internal memory which is faster than staticData but local to this process
// We will also use a 'Respond to Webhook' node after this to kill the loop
const staticData = $getWorkflowStaticData('global');

if (!staticData.seenIds) {
    staticData.seenIds = {};
}

if (staticData.seenIds[msgId]) {
    return { json: { isDuplicate: true, msgId: msgId } };
}

staticData.seenIds[msgId] = new Date().getTime();

return { 
    json: { 
        isDuplicate: false, 
        msgId: msgId, 
        ...$json 
    } 
};
